/**
 * 中文名 → 编号。同一名字对应多个编号时只留第一个 ——
 * 「晕」有 17 和 34、「OK」有 124 等，取编号小的那个。
 */
const FACE_IDS = (() => {
  const map = new Map()
  for (const [id, name] of FACE_NAMES) {
    if (!map.has(name)) map.set(name, id)
  }
  return map
})()

/**
 * 349 之后的 QQ 表情（内置表只到 348）。
 *
 * 为什么单列一张：内置表是社区整理的通用表，停在「福萝卜(348)」。
 * QQ 之后又加了一大批，而且**真实群聊里用得不少** ——
 * 实测 294 次贴表情事件里，387（太好笑）一个就占 76 次，占 26%。
 * 不补的话她收到的是「表情#387」，等于什么都没告诉她。
 *
 * 数据来源（2026-11-05 核对）：
 *   · 349~387：koishi QFace 表情库（koishi.js.org/QFace，同步于 2026-09-28），逐条核对
 *   · 425/428/449/462：orge-8/group-emoji-react 按 QQNT emojiId 重建的表（实测口径）
 *   两处重叠部分一致（387 = 太好笑），说明口径对得上，所以合并成一张。
 *
 * ⚠️ 这张表只用于**入站渲染**（把「贴了个 387」翻成「贴了个 太好笑」）。
 *    出站贴表情走 set_msg_emoji_like，由 NapCat 自己校验 id，不依赖这张表。
 *    出站发表情（face 段）仍然只认 FACE_NAMES + 官方目录，别把这张表接进去 ——
 *    它没经过发送验证，拿错了会让整条消息发不出去。
 */
const FACE_NAMES_EXT = new Map([
  [349, '坚强'], [350, '贴贴'], [351, '敲敲'], [352, '咦'], [353, '拜托'],
  [354, '尊嘟假嘟'], [355, '耶'], [356, '666'], [357, '裂开'], [358, '骰子'],
  [359, '包剪锤'], [360, '亲亲'], [361, '狗狗笑哭'], [362, '好兄弟'], [363, '狗狗可怜'],
  [364, '超级赞'], [365, '狗狗生气'], [366, '芒狗'], [367, '狗狗疑问'], [368, '奥特笑哭'],
  [369, '彩虹'], [370, '祝贺'], [371, '冒泡'], [372, '气呼呼'], [373, '忙'],
  [374, '波波流泪'], [375, '超级鼓掌'], [376, '跺脚'], [377, '嗨'], [378, '企鹅笑哭'],
  [379, '企鹅流泪'], [380, '真棒'], [381, '路过'], [382, 'emo'], [383, '企鹅爱心'],
  [384, '晚安'], [385, '太气了'], [386, '呜呜呜'], [387, '太好笑'],
  [425, '求放过'], [428, '收到'], [449, '+1'], [462, '无语']
])

/**
 * 名字 → 编号，**只查扩展表**（349 之后）。
 *
 * 单列一个函数而不是合进 faceIdOf()，是因为这两张表的可信度不一样：
 *   · 内置表（0~348）在 QQ 上真实发过 —— 错了整条消息会炸，所以 faceIdOf 要校验
 *   · 扩展表（349+）只核对过「客户端这么渲染」，没验证过发送 —— 不能进 faceIdOf
 *
 * 唯一的例外是贴表情（set_msg_emoji_like）：那边 id 错了只丢这一个动作，
 * 文字照发。所以她能收到「太好笑」，就让她能贴出去。
 */
export function extFaceIdOf(name) {
  const raw = String(name ?? '').trim()
  if (raw === '') return null
  for (const [id, label] of FACE_NAMES_EXT) {
    if (label === raw) return String(id)
  }
  return null
}

/**
 * 表情编号 → 中文名。查不到返回 null。
 *
 * 入站渲染统一走这里：经典表 + 扩展表。
 * 返回 null 时调用方应当显示「表情#编号」而不是瞎猜 —— 猜错比不知道更糟。
 */
export function faceNameOfId(id) {
  const n = Number(id)
  if (!Number.isSafeInteger(n) || n < 0) return null
  return FACE_NAMES.get(n) ?? FACE_NAMES_EXT.get(n) ?? null
}

/** 掐短文本，表情名别把整行撑爆。 */
function clip(text, max = 20) {
  const value = String(text ?? '').trim()
  return value.length > max ? `${value.slice(0, max)}…` : value
}

/** 经典表情（face）：有 cid 就查中文名，查不到就把编号原样报出来。 */
export function faceTextOf(data) {
  const cid = String(data?.cid ?? data?.id ?? '').trim()
  if (cid === '') return '[表情]'
  // 走 faceNameOfId 而不是直接查 FACE_NAMES：349 之后的扩展表也要认，
  // 不然群友发个「太好笑(387)」，她看到的是一串编号。
  const name = faceNameOfId(cid)
  return name !== null ? `[表情:${name}]` : `[表情:${cid}]`
}

/**
 * 商城大表情（mface）：优先用 summary（官方给的表情标题），其次 key / emoji_id。
 * 都没有就退回「[表情]」，别让 default 分支把它渲染成 [mface] 这种没人看得懂的原始类型名。
 */
export function mfaceTextOf(data) {
  const summary = clip(data?.summary ?? '')
  if (summary !== '') return `[表情:${summary}]`
  const key = clip(data?.key ?? '')
  if (key !== '') return `[表情:${key}]`
  const emojiId = clip(data?.emoji_id ?? '')
  if (emojiId !== '') return `[表情:${emojiId}]`
  return '[表情]'
}

/** 任意表情段 → 文本；不是表情段返回空串。 */
export function emojiTextOf(segment) {
  switch (segment?.type) {
    case 'face':
      return faceTextOf(segment?.data)
    case 'mface':
      return mfaceTextOf(segment?.data)
    default:
      return ''
  }
}

/**
 * 出站：把「中文名或数字编号」解析成 face 段的 id —— **只查内置兜底表**。
 *
 * ⚠️ 这张表有 109 个幽灵 id（见 FACE_NAMES 上方注释），拿它的结果直接去发，
 *    协议端会报错并把整条消息搞没。
 *    所以**出站不要直接用这个函数** —— 走 lib/face-resolve.js 的 resolveFaceId()，
 *    那边先查官方目录、再做有效性校验。
 *    这里只作为「官方目录不可用时的兜底」和「入站渲染」。
 *
 * 返回 null 表示不认识 —— 调用方要报错，不能发空表情。
 */
export function faceIdOf(nameOrId) {
  const raw = String(nameOrId ?? '').trim()
  if (raw === '') return null
  // 纯数字直接当编号用（哪怕不在名表里，协议端也认）
  if (/^\d+$/.test(raw)) {
    const id = Number(raw)
    return Number.isSafeInteger(id) && id >= 0 ? id : null
  }
  // 中文名精确匹配
  const exact = FACE_IDS.get(raw)
  if (exact !== undefined) return exact
  // 允许带修饰的写法：「呲牙笑」这种在前面加修饰的。
  // 2026-11-04 修：原来是「整串包含任意表情名就认」，太松——实测
  // 「这个颜色好看」被解析成表情「色」、「我刚睡醒」被解析成「睡」，
  // 出站就会发一个完全不相干的表情，而协议端不报错，很难发现。
  // 现在收紧成三条：①单字名字必须精确命中，不参与模糊；②只认前缀；
  // ③整串不超过 8 个字，避免整句话被当成表情。
  for (const [name, id] of FACE_IDS) {
    if (name.length < 2) continue
    if (raw.length <= 8 && raw.startsWith(name)) return id
  }
  return null
}

/**
 * 出站：face 段。id 认不出来就抛错。
 *
 * ⚠️ 同上 —— 这是**未经官方目录校验**的版本，只在明确知道 id 有效时用。
 *    正常发消息请走 lib/face-resolve.js 的 resolveFaceSegment()。
 */
export function faceSegmentOf(nameOrId) {
  const id = faceIdOf(nameOrId)
  if (id === null) {
    throw new Error(`不认识的 QQ 表情：${String(nameOrId)}（可以给中文名如「呲牙」，或直接给编号）`)
  }
  return { type: 'face', data: { id: String(id) } }
}

/** 出站表情的可选清单，给工具描述用 —— 让 agent 知道能发什么。 */
export function faceNameList() {
  return [...FACE_IDS.entries()].map(([name, id]) => `${name}(${id})`)
}

/**
 * 按名字模糊搜本地两张表（内置 0~348 + 扩展 349+）。
 *
 * 为什么需要（2026-11-05 批次64）：
 *   qq_emoji_search 原来只走协议端的 search_sys_faces —— 那是 SnowLuma 的扩展
 *   action，我们跑的是 NapCat，没这个接口，所以**永远返回空**。
 *   而她被告知「不知道表情叫什么就查一下」，查出来是空，就等于没有表情可用。
 *
 * 排序：精确命中 → 前缀 → 包含。她打「敲打」就是要 38，
 * 不能让「敲敲」「敲敲」这类名字抢在前面。
 *
 * 只用于**搜索展示**，不改变 faceIdOf 的可信度分级 ——
 * 扩展表仍然不能进 face 段（发错 id 整条消息会消失）。
 *
 * @param {string} query 关键词；空串表示列出全部
 * @param {number} limit 最多几条
 * @returns {Array<{id: string, name: string}>}
 */
export function searchFaceNames(query, limit = 30) {
  const q = String(query ?? '').trim()
  const max = Math.max(1, Number(limit) || 30)
  const pool = []
  for (const [id, name] of FACE_NAMES) pool.push([String(id), String(name)])
  for (const [id, name] of FACE_NAMES_EXT) pool.push([String(id), String(name)])

  if (q === '') return pool.slice(0, max).map(([id, name]) => ({ id, name }))

  const out = []
  const seen = new Set()
  const push = (id, name) => {
    if (seen.has(id)) return
    seen.add(id)
    out.push({ id, name })
  }
  for (const [id, name] of pool) if (name === q) push(id, name)
  for (const [id, name] of pool) if (name !== q && name.startsWith(q)) push(id, name)
  for (const [id, name] of pool) if (name !== q && !name.startsWith(q) && name.includes(q)) push(id, name)
  return out.slice(0, max)
}
